#include "PluginEditor.h"
TB3030AudioProcessorEditor::TB3030AudioProcessorEditor(TB3030AudioProcessor&x):AudioProcessorEditor(&x),p(x){setSize(1180,650);title.setText("TB-3030   ACID BASS SYNTHESIZER",juce::dontSendNotification);title.setFont(25);title.setJustificationType(juce::Justification::centred);addAndMakeVisible(title);const char*ids[]={"wave","tuning","cutoff","resonance","envmod","decay","accent","drive","glide","volume","swing"};for(int i=0;i<11;++i){auto&k=knobs[i];k.setSliderStyle(juce::Slider::RotaryVerticalDrag);k.setTextBoxStyle(juce::Slider::TextBoxBelow,false,64,17);k.setName(ids[i]);addAndMakeVisible(k);atts.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],k));}
for(int i=0;i<16;++i){for(int n=24;n<=60;++n)notes[i].addItem(juce::MidiMessage::getMidiNoteName(n,true,true,3),n-23);notes[i].onChange=[this,i]{p.seq.steps[(size_t)i].note=notes[i].getSelectedId()+23;};addAndMakeVisible(notes[i]);auto setup=[this,i](juce::TextButton&b,const char*t,bool AcidStep::*field){b.setButtonText(t);b.setClickingTogglesState(true);b.onClick=[this,i,&b,field]{p.seq.steps[(size_t)i].*field=b.getToggleState();};addAndMakeVisible(b);};setup(on[i],juce::String(i+1).toRawUTF8(),&AcidStep::enabled);setup(acc[i],"A",&AcidStep::accent);setup(slide[i],"S",&AcidStep::slide);setup(up[i],"+",&AcidStep::octaveUp);setup(down[i],"-",&AcidStep::octaveDown);}
presets.addItemList(p.bank.names(),1);presets.setSelectedId(1);presets.onChange=[this]{p.loadPreset(presets.getSelectedId()-1);};addAndMakeVisible(presets);run.setClickingTogglesState(true);run.onClick=[this]{p.seq.setRunning(run.getToggleState());run.setButtonText(run.getToggleState()?"STOP":"RUN");};clear.onClick=[this]{p.seq.clear();refreshSteps();};random.onClick=[this]{juce::Random r;p.seq.randomise(r);refreshSteps();};save.onClick=[this]{juce::FileChooser c("Save TB-3030 bank",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory),"*.xml");if(c.browseForFileToSave(true))p.bank.saveUserBank(c.getResult());};load.onClick=[this]{juce::FileChooser c("Load TB-3030 bank",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory),"*.xml");if(c.browseForFileToOpen()){p.bank.loadUserBank(c.getResult());presets.clear();presets.addItemList(p.bank.names(),1);}};store.onClick=[this]{int i=juce::jmax(0,presets.getSelectedId()-1);p.storePreset(i,presets.getText()+" User");};for(auto*b:{&run,&clear,&random,&save,&load,&store})addAndMakeVisible(*b);refreshSteps();startTimerHz(30);}
void TB3030AudioProcessorEditor::refreshSteps(){for(int i=0;i<16;++i){auto&s=p.seq.steps[(size_t)i];on[i].setToggleState(s.enabled,juce::dontSendNotification);acc[i].setToggleState(s.accent,juce::dontSendNotification);slide[i].setToggleState(s.slide,juce::dontSendNotification);up[i].setToggleState(s.octaveUp,juce::dontSendNotification);down[i].setToggleState(s.octaveDown,juce::dontSendNotification);notes[i].setSelectedId(s.note-23,juce::dontSendNotification);}}
void TB3030AudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xffd9d2bf));g.setColour(juce::Colour(0xff252525));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(7),11,3);g.fillRoundedRectangle(16,305,getWidth()-32,270,6);g.setColour(juce::Colour(0xfff2ede2));g.drawText("NOTE",15,335,55,22,juce::Justification::centredRight);g.drawText("STEP",15,370,55,22,juce::Justification::centredRight);g.drawText("ACCENT",10,407,60,22,juce::Justification::centredRight);g.drawText("SLIDE",15,444,55,22,juce::Justification::centredRight);g.drawText("OCT +",15,481,55,22,juce::Justification::centredRight);g.drawText("OCT -",15,518,55,22,juce::Justification::centredRight);}
void TB3030AudioProcessorEditor::resized(){title.setBounds(20,12,getWidth()-40,38);int kw=(getWidth()-40)/11;for(int i=0;i<11;++i)knobs[i].setBounds(20+i*kw,56,kw-4,180);presets.setBounds(30,255,210,28);run.setBounds(260,255,80,28);clear.setBounds(350,255,80,28);random.setBounds(440,255,90,28);store.setBounds(550,255,80,28);save.setBounds(640,255,100,28);load.setBounds(750,255,100,28);int left=78;int sw=(getWidth()-left-20)/16;for(int i=0;i<16;++i){int x=left+i*sw;notes[i].setBounds(x,333,sw-3,25);on[i].setBounds(x,370,sw-3,28);acc[i].setBounds(x,407,sw-3,28);slide[i].setBounds(x,444,sw-3,28);up[i].setBounds(x,481,sw-3,28);down[i].setBounds(x,518,sw-3,28);}}
void TB3030AudioProcessorEditor::timerCallback(){int c=p.seq.getCurrentStep();for(int i=0;i<16;++i)on[i].setColour(juce::TextButton::buttonColourId,i==c?juce::Colour(0xffca1736):(on[i].getToggleState()?juce::Colour(0xffa8905c):juce::Colour(0xffede8dc)));}
